start=s.index('class SimplePie_Restriction\n')
s=s[:start]+'''class SimplePie_Restriction implements \\Stringable
{
	/**
	 * Constructor, used to input the data
	 *
	 * For documentation on all the parameters, see the corresponding
	 * properties and their accessors
	 *
	 * @param string|null $relationship Relationship ('allow'/'deny'), see get_relationship()
	 * @param string|null $type Type of restriction, see get_type()
	 * @param string|null $value Restricted values, see get_value()
	 */
	public function __construct(
		public $relationship = null,
		public $type = null,
		public $value = null
	) {
	}

	/**
	 * String-ified version
	 *
	 * @return string
	 */
	public function __toString(): string
	{
		// There is no $this->data here
		return md5(serialize($this));
	}

	/**
	 * Get the relationship
	 *
	 * @return string|null Either 'allow' or 'deny'
	 */
	public function get_relationship()
	{
		return $this->relationship;
	}

	/**
	 * Get the type
	 *
	 * @return string|null
	 */
	public function get_type()
	{
		return $this->type;
	}

	/**
	 * Get the list of restricted things
	 *
	 * @return string|null
	 */
	public function get_value()
	{
		return $this->value;
	}
}
'''
